#!/usr/bin/env python3
"""MIT. Retain, map and review complete humanitarian table editions."""
from __future__ import annotations
import argparse
import json
from pathlib import Path
import signal
import sys

from humanitarian_workspace import (
    HumanitarianWorkspace, InputError, MAX_REQUEST, strict_json,
)
from humanitarian_http import HumanitarianServer


def read_input(path):
    with Path(path).open("rb") as stream:
        body = stream.read(MAX_REQUEST + 1)
    if len(body) > MAX_REQUEST:
        raise InputError("Complete JSON input exceeds 1 MiB")
    return strict_json(body)


def call(ws, operation, args):
    if not isinstance(args, dict):
        raise InputError("Operation arguments must be a complete object")
    if operation == "state":
        return ws.state()
    if operation == "source":
        return ws.source(args["id"])
    if operation == "source.add":
        path = Path(args["file"])
        with path.open("rb") as stream:
            return ws.add_source(stream, args.get("label", path.name), args.get("name", path.name))
    if operation == "source.table":
        return ws.table_rows(args["source"], args.get("table", "data"),
                             args.get("offset", 0), args.get("limit", 8))
    if operation == "reference.save":
        return ws.save_reference(args)
    if operation == "reference":
        return ws.reference(args["id"])
    if operation == "mapping.save":
        return ws.save_mapping(args)
    if operation == "mapping":
        return ws.mapping(args["id"])
    if operation == "alias.save":
        return ws.save_alias(args)
    if operation == "alias":
        return ws.alias(args["id"])
    if operation == "review.save":
        return ws.save_review(args)
    if operation == "review":
        return ws.review(args["id"], args.get("revision"))
    if operation == "reviews":
        return ws.reviews()
    if operation == "history":
        return ws.history(args["id"])
    if operation == "report":
        return ws.report(args["id"], args.get("revision"))
    if operation == "rows":
        return ws.rows(
            args["id"], args.get("revision"), args.get("edition", 0),
            args.get("offset", 0), args.get("limit", 50), args.get("issues", False),
        )
    if operation == "output.rows":
        return ws.output_rows(args["id"], args.get("revision"), args.get("edition", 0),
                              args.get("output"), args.get("offset", 0), args.get("limit", 50))
    if operation == "comparison.rows":
        return ws.comparison_rows(args["id"], args.get("revision"),
                                  args.get("offset", 0), args.get("limit", 50))
    if operation == "request":
        return ws.request(args["id"])
    if operation == "review.export":
        return ws.export_review(args["id"], Path(args["output"]), args.get("revision"))
    if operation == "report.export":
        return ws.write_report(args["id"], Path(args["output"]), args.get("revision"))
    if operation == "receive":
        return ws.receive_review(Path(args["file"]))
    if operation == "query":
        return ws.query(args["build"], args.get("query", {}))
    if operation == "dataset.export":
        return ws.export_dataset(args["build"], Path(args["output"]))
    raise InputError("Unknown documented humanitarian operation: " + str(operation))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", required=True, help="Original private humanitarian workspace")
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("init", help="Create the private source and review workspace")
    sub.add_parser("list", help="Read the complete saved source, reference, mapping and review inventory")
    sub.add_parser("binding", aliases=["bind"], help="Read the original managed source and workspace binding")
    action = sub.add_parser("call", help="Run one operation with its complete {operation,args} JSON")
    action.add_argument("--input", required=True)
    source = sub.add_parser("source", help="Retain and inventory a complete original table source")
    source.add_argument("--file", required=True)
    source.add_argument("--label", required=True)
    for kind in ("reference", "mapping", "alias", "review"):
        save = sub.add_parser("save-" + kind, help="Save the complete original " + kind + " request")
        save.add_argument("--input", required=True)
    for name in ("reference", "mapping", "alias", "review", "history", "report", "export", "report-export"):
        command = sub.add_parser(name)
        command.add_argument("--id", required=True)
        if name in {"review", "report", "export", "report-export"}:
            command.add_argument("--revision", type=int)
        if name in {"export", "report-export"}:
            command.add_argument("--output", required=True)
    rows = sub.add_parser("rows", help="Read original normalized rows and resolution issues")
    rows.add_argument("--id", required=True)
    rows.add_argument("--revision", type=int)
    rows.add_argument("--edition", type=int, default=0)
    rows.add_argument("--offset", type=int, default=0)
    rows.add_argument("--limit", type=int, default=50)
    rows.add_argument("--issues", action="store_true")
    for name in ("output-rows", "comparison-rows"):
        page = sub.add_parser(name, help="Read a complete saved reporting page")
        page.add_argument("--id", required=True)
        page.add_argument("--revision", type=int)
        page.add_argument("--offset", type=int, default=0)
        page.add_argument("--limit", type=int, default=50)
        if name == "output-rows":
            page.add_argument("--edition", type=int, default=0)
            page.add_argument("--output", required=True)
    table = sub.add_parser("source-table", help="Read full original physical table rows")
    table.add_argument("--source", required=True)
    table.add_argument("--table", default="data")
    table.add_argument("--offset", type=int, default=0)
    table.add_argument("--limit", type=int, default=8)
    request = sub.add_parser("request", help="Read the result of an original request identifier")
    request.add_argument("--id", required=True)
    receive = sub.add_parser("receive", help="Reconstruct a complete source and review-history package")
    receive.add_argument("--file", required=True)
    query = sub.add_parser("query", help="Query one original Dataset build")
    query.add_argument("--build", required=True)
    query.add_argument("--params", default="{}")
    dataset = sub.add_parser("dataset", help="Export the complete original Dataset files")
    dataset.add_argument("--build", required=True)
    dataset.add_argument("--output", required=True)
    serve = sub.add_parser("serve", help="Open the original authenticated private console")
    serve.add_argument("--port", type=int, default=0)
    serve.add_argument("--expected-binding")
    serve.add_argument("--startup-format", choices=["json"], default="json")
    args = parser.parse_args(argv)
    if args.command in {"bind", "binding"}:
        from humanitarian_managed import inspect_binding
        print(json.dumps(inspect_binding(args.workspace), ensure_ascii=False, allow_nan=False))
        return
    if args.command == "serve":
        from humanitarian_managed import require_binding
        binding = require_binding(args.workspace, args.expected_binding)
    with HumanitarianWorkspace(args.workspace, create=args.command == "init") as ws:
        command = args.command
        if command in {"init", "list"}:
            result = ws.state()
        elif command == "call":
            original = read_input(args.input)
            if not isinstance(original, dict) or set(original) != {"operation", "args"}:
                raise InputError("Call input must contain its exact operation and complete arguments")
            result = call(ws, original["operation"], original["args"])
        elif command == "source":
            path = Path(args.file)
            with path.open("rb") as stream:
                result = ws.add_source(stream, args.label, path.name)
        elif command.startswith("save-"):
            method = {
                "save-reference": ws.save_reference, "save-mapping": ws.save_mapping,
                "save-alias": ws.save_alias, "save-review": ws.save_review,
            }[command]
            result = method(read_input(args.input))
        elif command in {"reference", "mapping", "alias", "request", "history"}:
            result = getattr(ws, command)(args.id)
        elif command in {"review", "report"}:
            result = getattr(ws, command)(args.id, args.revision)
        elif command == "rows":
            result = ws.rows(args.id, args.revision, args.edition, args.offset, args.limit, args.issues)
        elif command == "output-rows":
            result = ws.output_rows(args.id, args.revision, args.edition, args.output, args.offset, args.limit)
        elif command == "comparison-rows":
            result = ws.comparison_rows(args.id, args.revision, args.offset, args.limit)
        elif command == "source-table":
            result = ws.table_rows(args.source, args.table, args.offset, args.limit)
        elif command == "export":
            result = ws.export_review(args.id, Path(args.output), args.revision)
        elif command == "report-export":
            result = ws.write_report(args.id, Path(args.output), args.revision)
        elif command == "receive":
            result = ws.receive_review(Path(args.file))
        elif command == "query":
            result = ws.query(args.build, strict_json(args.params))
        elif command == "dataset":
            result = ws.export_dataset(args.build, Path(args.output))
        elif command == "serve":
            if not 0 <= args.port <= 65535:
                raise InputError("Port must be from 0 to 65535")
            server = HumanitarianServer(ws, args.port, binding)
            print(json.dumps(server.launch_record, ensure_ascii=False, separators=(",", ":"), allow_nan=False), flush=True)

            def terminate(_signal, _frame):
                raise KeyboardInterrupt

            previous = signal.signal(signal.SIGTERM, terminate)
            try:
                server.serve_forever(poll_interval=0.2)
            except KeyboardInterrupt:
                pass
            finally:
                signal.signal(signal.SIGTERM, signal.SIG_IGN)
                signal.signal(signal.SIGINT, signal.SIG_IGN)
                try:
                    server.server_close()
                finally:
                    signal.signal(signal.SIGTERM, previous)
            return
        print(json.dumps(result, ensure_ascii=False, allow_nan=False, indent=2))


if __name__ == "__main__":
    try:
        main()
    except (InputError, OSError, ValueError, KeyError) as error:
        print("Humanitarian: " + str(error), file=sys.stderr)
        sys.exit(1)

"""MIT. Humanitarian routes on the original private loopback operator server."""
from __future__ import annotations
import os
from pathlib import Path
import shutil
from urllib.parse import parse_qs, unquote

from humanitarian_workspace import InputError, MAX_SOURCE, MAX_ARCHIVE, MAX_REQUEST, strict_json
from server import OperatorServer, Handler

HERE = Path(__file__).resolve().parent


def single_query(target):
    query = parse_qs(target.query, keep_blank_values=True)
    if any(len(values) != 1 for values in query.values()):
        raise InputError("Repeated query parameters are not accepted")
    return {key: values[0] for key, values in query.items()}


class HumanitarianHandler(Handler):
    server_version = "SF30-Humanitarian"

    def _get(self):
        target = self._gate(api=False)
        if target.path == "/api/launch":
            self._gate()
            return self._json(self.server.launch_record)
        if not target.path.startswith("/api/humanitarian/"):
            return super()._get()
        self._gate()
        query = single_query(target)
        ws = self.server.workspace
        route = target.path[len("/api/humanitarian/"):]
        revision = int(query["revision"]) if query.get("revision") else None
        if route == "state":
            result = ws.state()
        elif route == "source":
            result = ws.source(query["id"])
        elif route == "source-table":
            result = ws.table_rows(query["source"], query.get("table", "data"),
                                   int(query.get("offset", "0")), int(query.get("limit", "8"))
        elif route == "reference":
            result = ws.reference(query["id"])
        elif route == "mapping":
            result = ws.mapping(query["id"])
        elif route == "alias":
            result = ws.alias(query["id"])
        elif route == "reviews":
            result = ws.reviews()
        elif route == "review":
            result = ws.review(query["id"], revision)
        elif route == "history":
            result = ws.history(query["id"])
        elif route == "request":
            # A read-only lookup is the original pre-dispatch reconciliation route.
            # An absent request may be sent with its retained complete body and UUID.
            try:
                result = ws.request(query["id"])
            except InputError as error:
                if str(error) != "Unknown completed request":
                    raise
                return self._json({"error": str(error), "requestNotFound": True}, 404)
        elif route == "report":
            result = ws.report(query["id"], revision)
        elif route == "rows":
            if query.get("issues", "0") not in {"0", "1"}:
                raise InputError("Choose all rows or rows with issues explicitly")
            result = ws.rows(
                query["id"], revision, int(query.get("edition", "0")),
                int(query.get("offset", "0")), int(query.get("limit", "50")),
                query.get("issues") == "1",
            )
        elif route == "output-rows":
            result = ws.output_rows(query["id"], revision, int(query.get("edition", "0")),
                                    query.get("output"), int(query.get("offset", "0")),
                                    int(query.get("limit", "50")))
        elif route == "comparison-rows":
            result = ws.comparison_rows(query["id"], revision, int(query.get("offset", "0")),
                                        int(query.get("limit", "50")))
        elif route == "export":
            kind = query.get("kind", "workspace")
            if kind not in {"workspace", "report"}:
                raise InputError("Export kind must be workspace or report")
            with ws.mutex, ws.scratch() as temporary:
                path = temporary / ("humanitarian-" + kind + ".zip")
                if kind == "workspace":
                    ws.export_review(query["id"], path, revision)
                else:
                    ws.write_report(query["id"], path, revision)
                self._download(path, path.name, "application/zip")
            return
        else:
            return self._json({"error": "Unknown humanitarian operation"}, 404)
        self._json(result)

    def _post(self):
        target = self._gate()
        ws = self.server.workspace
        if target.path == "/api/source":
            name = unquote(self.headers.get("X-Humanitarian-Name", "table.csv"))
            label = unquote(self.headers.get("X-Humanitarian-Label", name))
            return self._json(ws.add_source(self._body(MAX_SOURCE), label, name), 201)
        if target.path == "/api/import":
            with ws.mutex, ws.scratch() as temporary:
                path = temporary / "complete-input.zip"
                with path.open("xb") as stream:
                    os.fchmod(stream.fileno(), 0o600)
                    shutil.copyfileobj(self._body(MAX_ARCHIVE), stream, 65536)
                    stream.flush()
                    os.fsync(stream.fileno())
                return self._json(ws.receive_review(path), 201)
        if not target.path.startswith("/api/humanitarian/"):
            return super()._post()
        body = strict_json(self._body(MAX_REQUEST).read())
        if not isinstance(body, dict):
            raise InputError("Expected a complete humanitarian operation object")
        methods = {
            "/api/humanitarian/reference": ws.save_reference,
            "/api/humanitarian/mapping": ws.save_mapping,
            "/api/humanitarian/alias": ws.save_alias,
            "/api/humanitarian/review": ws.save_review,
        }
        method = methods.get(target.path)
        if method is None:
            return self._json({"error": "Unknown humanitarian operation"}, 404)
        self._json(method(body), 201)


class HumanitarianServer(OperatorServer):
    def __init__(self, workspace, port=0, binding=None):
        super().__init__(
            workspace, port, assets_directory=HERE / "public",
            handler_class=HumanitarianHandler,
        )
        from humanitarian_managed import startup, inspect_binding
        self.launch_record = startup(self, binding or inspect_binding(workspace.root))

#!/usr/bin/env node
// MIT. Select the original Python console and keep the native Node identity.
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { isAbsolute } from 'node:path';

const args = process.argv.slice(2);
const at = args.indexOf('--python');
let python = process.env.CODEX_PRIMARY_RUNTIME_PYTHON || process.env.SF30_HUMANITARIAN_PYTHON || 'python3';
if (at >= 0) {
  if (at + 1 >= args.length || !isAbsolute(args[at + 1])) throw new Error('Select an absolute existing Python executable');
  python = args[at + 1]; args.splice(at, 2);
}
if (args.includes('--python')) throw new Error('Select Python once');
const child = spawn(python, ['-B', fileURLToPath(new URL('./humanitarian_cli.py', import.meta.url)), ...args], {
  stdio: 'inherit', windowsHide: true, env: { ...process.env, SF30_XML_NODE: process.execPath },
});
let closed = false;
const forward = signal => { if (!closed) child.kill(signal); };
const sigterm = () => forward('SIGTERM'), sigint = () => forward('SIGINT');
process.on('SIGTERM', sigterm); process.on('SIGINT', sigint);
child.once('error', error => { console.error(error.message); process.exitCode = 1; });
child.once('close', (code, signal) => {
  closed = true; process.removeListener('SIGTERM', sigterm); process.removeListener('SIGINT', sigint);
  process.exitCode = code ?? (signal === 'SIGINT' ? 130 : signal === 'SIGTERM' ? 143 : 1);
});

// MIT. Complete humanitarian table and review operations over the original authenticated loopback host.
const JSON_LIMIT=1024*1024, ARCHIVE_LIMIT=2*1024*1024*1024;
const HEX=/^[a-f0-9]{64}$/;
function need(value,message){if(!value)throw new TypeError(message);}
function checkedRevision(value){need(value===undefined||value===null||Number.isSafeInteger(value)&&value>=1,'Select a saved positive revision');return value;}
function id(value){need(typeof value==='string'&&HEX.test(value),'Select an original SHA-256 identity');return value;}
function identifier(value){need(typeof value==='string'&&/^[A-Za-z][A-Za-z0-9_.-]{0,79}$/.test(value),'Select an original named identifier of at most 80 characters');return value;}
function request(value){need(value&&typeof value==='object'&&!Array.isArray(value)&&typeof value.requestId==='string'&&/^[A-Za-z][A-Za-z0-9_.-]{0,79}$/.test(value.requestId),'Retain the complete original request and requestId');return value;}
function originalURL(input){
  const raw=typeof input==='string'?input:input?.console||input?.url;const url=new URL(raw);
  const token=url.hash.slice(1)||input?.token;
  need(url.protocol==='http:'&&url.hostname==='127.0.0.1'&&!url.username&&!url.password&&!url.search&&url.pathname==='/'&&Number(url.port||80)>=1&&Number(url.port||80)<=65535&&/^[A-Za-z0-9_-]{43}$/.test(token),'Select the original private humanitarian console URL');
  url.hash='';return{base:url.origin,token};
}
function blob(value,maximum,label){
  const result=value instanceof Blob?value:typeof value==='string'?new Blob([value]):value instanceof ArrayBuffer||ArrayBuffer.isView(value)?new Blob([value]):null;
  need(result&&result.size<=maximum,label+' requires its complete original bytes within the documented limit');return result;
}
function encoded(value,maximum=JSON_LIMIT){const text=JSON.stringify(value);need(typeof text==='string','Expected complete JSON');const body=new Blob([text+'\n'],{type:'application/json'});need(body.size<=maximum,'Complete JSON exceeds its documented bound');return body;}
export class HumanitarianHttpError extends Error{
  constructor(status,body){super(body?.error||'humanitarian HTTP '+status);this.name='HumanitarianHttpError';this.status=status;this.body=body;this.uncertain=status>=500;}
}
export class HumanitarianClient{
  #base;#token;#fetch;#timeout;#active=new Set();#closed=false;#closing=null;
  constructor(connection,{fetch:fetcher=globalThis.fetch,timeoutMs=120000}={}){
    const selected=originalURL(connection);this.#base=selected.base;this.#token=selected.token;
    need(typeof fetcher==='function'&&Number.isSafeInteger(timeoutMs)&&timeoutMs>=1000&&timeoutMs<=3600000,'Choose the existing fetch transport and a bounded timeout');
    this.#fetch=fetcher;this.#timeout=timeoutMs;
  }
  get origin(){return this.#base;}
  async #response(route,{method='GET',params={},body,headers={},signal}={}){
    need(!this.#closed,'The original humanitarian client has closed admission');
    need(typeof route==='string'&&/^\/api\/[a-z/-]+$/.test(route),'Choose a documented humanitarian route');
    const url=new URL(route,this.#base);for(const[key,value]of Object.entries(params))if(value!==undefined&&value!==null)url.searchParams.set(key,String(value));
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(Error('Original humanitarian request exceeded its selected timeout')),this.#timeout);
    const aborted=()=>controller.abort(signal.reason);if(signal?.aborted)aborted();else signal?.addEventListener('abort',aborted,{once:true});
    let finish,reader=null,streamController=null,ended=false,fetchSettled=false,bodyEnded=false,reads=0,cancellation=null;
    const done=new Promise(resolve=>{finish=resolve;});this.#active.add(done);
    const release=()=>{if(ended||!fetchSettled||!bodyEnded||reads||cancellation)return;ended=true;clearTimeout(timer);signal?.removeEventListener('abort',aborted);controller.signal.removeEventListener('abort',expired);this.#active.delete(done);finish();};
    const cancelReader=reason=>{
      if(!reader)return Promise.resolve();
      if(cancellation)return cancellation;
      // Keep the accepted reader until cancel and every outstanding read settle.
      const pending=Promise.resolve().then(()=>reader.cancel(reason));
      cancellation=pending;
      pending.then(()=>{bodyEnded=true;cancellation=null;release();},()=>{bodyEnded=true;cancellation=null;release();});
      return pending;
    };
    const expired=()=>{
      const error=controller.signal.reason||Error('Original transfer ended');
      try{streamController?.error(error);}catch{}
      // A pre-header abort remains owned by the original awaited fetch/catch.
      if(reader)cancelReader(error).catch(()=>{});
    };
    controller.signal.addEventListener('abort',expired,{once:true});
    try{
      const response=await this.#fetch(url,{method,body,redirect:'error',signal:controller.signal,headers:{authorization:'Bearer '+this.#token,...headers}});
      fetchSettled=true;
      if(controller.signal.aborted){
        if(response.body){reader=response.body.getReader();await cancelReader(controller.signal.reason);}
        bodyEnded=true;release();throw controller.signal.reason||Error('Original transfer ended');
      }
      if(!response.ok){const text=await response.text();let value;try{value=JSON.parse(text);}catch{value={error:text};}throw new HumanitarianHttpError(response.status,value);}
      if(!response.body){bodyEnded=true;release();return response;}
      reader=response.body.getReader();
      const stream=new ReadableStream({
        start(value){streamController=value;},
        async pull(value){
          reads++;
          try{const item=await reader.read();if(item.done){bodyEnded=true;value.close();}else value.enqueue(item.value);}
          catch(error){try{value.error(error);}catch{}await cancelReader(error).catch(()=>{});}
          finally{reads--;release();}
        },
        async cancel(reason){await cancelReader(reason);}
      });
      if(controller.signal.aborted)expired();
      return new Response(stream,{status:response.status,statusText:response.statusText,headers:response.headers});
    }catch(error){
      fetchSettled=true;
      if(reader)await cancelReader(error).catch(()=>{});
      bodyEnded=true;release();throw error;
    }
  }
  async #get(route,params){return(await this.#response(route,{params})).json();}
  async #post(route,value){return(await this.#response(route,{method:'POST',body:encoded(value),headers:{'content-type':'application/json'}})).json();}
  launch(){return this.#get('/api/launch');}
  state(){return this.#get('/api/humanitarian/state');}
  async addSource(original,{name,label}){
    need(typeof name==='string'&&name&&typeof label==='string'&&label,'Retain the complete source filename and label');
    return(await this.#response('/api/source',{method:'POST',body:blob(original,100*1024*1024,'Original table source'),headers:{'content-type':'application/octet-stream','X-Humanitarian-Name':encodeURIComponent(name),'X-Humanitarian-Label':encodeURIComponent(label)}})).json();
  }
  source(value){return this.#get('/api/source',{id:id(value)});}
  sourceTable(source,{table='data',offset=0,limit=8}={}){need(typeof table==='string'&&table&&Number.isSafeInteger(offset)&&offset>=0&&Number.isSafeInteger(limit)&&limit>=1&&limit<=20,'Choose one complete original table row window');return this.#get('/api/humanitarian/source-table',{source:id(source),table,offset,limit});}
  saveReference(input){return this.#post('/api/humanitarian/reference',request(input));}
  reference(value){return this.#get('/api/humanitarian/reference',{id:id(value)});}
  saveMapping(input){return this.#post('/api/humanitarian/mapping',request(input));}
  mapping(value){return this.#get('/api/humanitarian/mapping',{id:id(value)});}
  saveAlias(input){return this.#post('/api/humanitarian/alias',request(input));}
  alias(value){return this.#get('/api/humanitarian/alias',{id:id(value)});}
  saveReview(input){return this.#post('/api/humanitarian/review',request(input));}
  review(value,revision){return this.#get('/api/humanitarian/review',{id:identifier(value),revision:checkedRevision(revision)});}
  reviews(){return this.#get('/api/humanitarian/reviews');}
  history(value){return this.#get('/api/humanitarian/history',{id:identifier(value)});}
