    const tag=String(attempt).padStart(4,'0')+'-'+randomUUID(),stdout=join(folder,'stdout-'+tag+'.json'),stderr=join(folder,'stderr-'+tag+'.log');
    const out=await open(stdout,'wx',0o600),err=await open(stderr,'wx',0o600);
